rule.definition:
a!localVariables(
  local!recipient:
    if(
      contains(
        {
          #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[1]
        },
        tointeger(ri!statusId)
      ),
      {#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177083",#"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066240", #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066222"},
      if(
        contains(
          {
            #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[2]
          },
          tointeger(ri!statusId)
        ),
        ri!selectedGroup,
        null
      )
    ),

  local!users:if(
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!recipient),
    #"SYSTEM_SYSRULES_forEach"(
      items: local!recipient,
      expression: a!groupMembers(fv!item)
    ),
    null
  ),

  local!recipients:if(
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!recipient),
    a!flatten(#"SYSTEM_SYSRULES_forEach"(
      items: local!users,
      expression: property(fv!item,"data",null)
    )
    ),
    null
  ),  


  if(
    contains(
      {
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[6],
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[7],
        #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[8]
      },
      tointeger(ri!statusId)
    ),
    toemailrecipient(toemailaddress(#"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4718496")),
    toemailrecipient(toemailaddress(local!recipients))
  )

)
